"""Small mathematical illustrations embedded in the technical articles."""
def secant_demo():
    points=' '.join(f'{50+210*x:.1f},{290-36*x*x:.1f}' for x in [i/100 for i in range(241)])
    return '''<div class="secant-demo" data-secant><svg viewBox="0 0 660 330" role="img" aria-label="平方函数上的割线逐渐靠近切线"><path d="M50 20V290H620" fill="none" stroke="#a0aaa4"/><polyline points="'''+points+'''" fill="none" stroke="#173431" stroke-width="3"/><path d="M155 290L554 153.2" stroke="#68716c" stroke-width="2" stroke-dasharray="6 5"/><line data-secant-line x1="155" y1="299" x2="554" y2="128" stroke="#b8492c" stroke-width="3"/><circle cx="260" cy="254" r="6" fill="#173431"/><circle data-secant-point cx="365" cy="209" r="6" fill="#b8492c"/><text x="225" y="280" font-size="14">P (1, 1)</text><text x="490" y="65" font-size="16">f(x) = x²</text><text x="72" y="36" font-size="13">实线：割线　虚线：切线</text></svg><label>移动第二个点：h <input data-secant-slider type="range" min="0.01" max="1.2" step="0.01" value="0.5"></label><output data-secant-output>h = 0.50；割线斜率 = 2.50；切线斜率 = 2</output><p>拖动滑块，观察割线方向的变化。h 始终不等于零。</p></div>'''
